const projects=[
{title:'A CRM that follows the lead, not the spreadsheet',category:'Commerce',img:'crm',name:'Priya Nair',role:'Growth engineer',initials:'PN',desc:'Tracking e-commerce leads from first visit to first order.',query:'crm leads e-commerce sales pipeline',headline:'a CRM for tracking leads on an e-commerce system?',question:'How do you know which shoppers are worth a personal follow-up before the sales team drowns in contacts?',approach:'Start from the store’s own events — cart, wishlist, repeat visit — and turn only a few of them into leads. Keep the pipeline to three stages a small team can actually review each morning.',tradeoff:'Fewer, richer leads mean some buyers are never contacted. In return the team trusts the list and acts on it, instead of exporting it to yet another spreadsheet.',lesson:'Measure lead-to-order time and who closed it. A pipeline nobody opens is worse than no pipeline.'},
{title:'Onboarding that feels like a conversation',category:'Product & design',img:'onboarding',name:'Sofia Reyes',role:'Product designer',initials:'SR',desc:'Replacing setup forms with a few friendly questions.',query:'conversational onboarding signup chat activation',headline:'a conversational-based onboarding experience?',question:'What should a new user tell us — and accomplish — before we ask them to configure anything?',approach:'Ask two or three plain questions, offer choices as tappable cards, and build an editable example from the answers so the first session begins with progress.',tradeoff:'Conversational steps feel slower to power users, so every question needs a skip and sensible defaults behind it.',lesson:'Track time to a meaningful outcome. A completed tour can look healthy while users still struggle to begin.'},
{title:'A knowledge base that answers with sources',category:'AI & automation',img:'knowledge',name:'Maya Chen',role:'AI product engineer',initials:'MC',desc:'Turning scattered team knowledge into answers you can trust.',query:'ai knowledge base search documents retrieval sources',headline:'an AI knowledge base that answers with sources?',question:'How do you help a team find a reliable answer without asking them to learn another tool?',approach:'Start with a narrow collection of reviewed documents. Retrieve relevant passages before generating an answer, and show the source beside every claim. Make “I don’t know” a useful outcome.',tradeoff:'A smaller, reviewed knowledge set produces fewer answers, but makes mistakes easier to investigate. Freshness and ownership matter as much as retrieval quality.',lesson:'Measure whether someone found a supported answer, not whether the assistant replied. Give document owners a queue of unanswered questions.'},
{title:'A marketplace for independent makers',category:'Platforms',img:'marketplace',name:'Oliver Park',role:'Marketplace strategist',initials:'OP',desc:'Connecting small makers with people who care about craft.',query:'marketplace makers niche commerce shop',headline:'a marketplace for independent makers?',question:'How does a small marketplace create useful matches before it has scale?',approach:'Choose one narrow buyer need and recruit a small set of makers by hand. Curate the first listings around comparable attributes and learn from unsuccessful searches.',tradeoff:'Manual curation slows expansion but reveals what buyers really need to compare. A large catalog can hide a lack of useful matches.',lesson:'Validate repeated buyer demand before automating seller onboarding. Density within a niche matters more than total listing count.'},
{title:'A subscription dashboard people check on purpose',category:'Commerce',img:'subscriptions',name:'Daniel Brooks',role:'Billing product lead',initials:'DB',desc:'Making recurring payments visible, predictable and easy to change.',query:'subscription dashboard recurring payments billing',headline:'a dashboard for managing subscriptions and renewals?',question:'How do you show recurring charges so customers feel in control instead of surprised?',approach:'Lead with what renews next and what it will cost. Group the rest by cadence, and put pause, skip and cancel one tap away from each row.',tradeoff:'Easy cancellation can lower short-term retention, but it reduces chargebacks and support tickets and earns trust that brings people back.',lesson:'Watch saves from pause and skip, not just cancellations. The best retention lever is a renewal nobody regrets.'}
];
const $=id=>document.getElementById(id);let view='projects',filter='All';let requests=[],submissions=[];try{requests=JSON.parse(localStorage.getItem('knowhow-requests')||'[]');submissions=JSON.parse(localStorage.getItem('knowhow-submissions')||'[]')}catch{}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('knowhow-requests',JSON.stringify(requests));localStorage.setItem('knowhow-submissions',JSON.stringify(submissions));return true}catch{alert('Your browser could not save this entry. Please copy it before closing.');return false}}
const art=p=>`<div class="art"><img src="assets/${p.img}.png" alt="" loading="lazy"></div>`;
function render(){const q=$('search').value.toLowerCase().trim();$('sectionLabel').textContent=view==='projects'?'THE PROJECT LIBRARY':view==='people'?'THE MINDS BEHIND THE WORK':'IDEAS LOOKING FOR THEIR PEOPLE';$('sectionTitle').textContent=view==='projects'?(q?'Find your starting point.':'Start with a possibility.'):view==='people'?'Find someone who gets it.':'Start a new possibility.';$('filters').hidden=view==='requests';let list=projects.filter(p=>(filter==='All'||p.category===filter)&&(!q||`${p.title} ${p.category} ${p.name} ${p.query}`.toLowerCase().includes(q)));if($('sort').value==='title')list=[...list].sort((a,b)=>a.title.localeCompare(b.title));if(view==='requests'){$('grid').innerHTML=requests.filter(r=>!q||`${r.title} ${r.details}`.toLowerCase().includes(q)).map(r=>`<article class="card request-card"><span class="tag">LOCAL PROJECT REQUEST</span><h3>${esc(r.title)}</h3><p>${esc(r.details)}</p><span class="status">Saved on this device · ${esc(r.stage)}</span></article>`).join('')||`<div class="empty"><h3>A good question is a great start.</h3><p>No requests here yet. Describe what you want to build.</p><button class="primary" onclick="requestForm()">Post the first request</button></div>`;return}$('grid').innerHTML=list.map(p=>view==='people'?`<button class="card person-card" data-person="${projects.indexOf(p)}"><div class="avatar">${p.initials}</div><h3>${p.name}</h3><span class="tag">${p.role}</span><p style="margin-top:14px">${p.desc}</p><span class="status">Explore their thinking →</span></button>`:`<button class="card" data-project="${projects.indexOf(p)}">${art(p)}<div class="card-body"><span class="tag">${p.category}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="person"><span class="avatar">${p.initials}</span><span>${p.name}<small>${p.role}</small></span><span class="read">Read the thinking →</span></div></div></button>`).join('')||`<div class="empty"><h3>This idea hasn’t found its case study yet.</h3><p>Try fewer words, explore another category, or request the knowhow you need.</p><button class="primary" onclick="requestForm()">Request this project</button></div>`}
function open(html){$('modal').innerHTML=html;if(!$('dialog').open)$('dialog').showModal()}
function project(i){const p=projects[i];open(`<div class="modal-art"><img src="assets/${p.img}.png" alt=""></div><span class="tag">${p.category} · Illustrative case study</span><h2>${p.title}</h2><p>${p.question}</p><h3>The approach</h3><p>${p.approach}</p><h3>The tradeoff</h3><p>${p.tradeoff}</p><h3>What to take with you</h3><p>${p.lesson}</p><button class="primary" onclick="person(${i})">Meet ${p.name.split(' ')[0]}</button>`)}
function person(i){const p=projects[i];open(`<span class="tag">EXAMPLE PROFILE</span><h2>${p.name}</h2><p>${p.role} · ${p.category}</p><h3>How I think about the work</h3><p>${p.approach}</p><h3>Explore the project</h3><p>${p.title}</p><button class="outline" onclick="project(${i})">Read the case study</button><h3>Have a related challenge?</h3><p>This is an illustrative profile. You can save a project brief locally, ready to share with a real collaborator.</p><button class="primary" onclick="requestForm('${p.name}')">Create a related brief</button>`)}
function requestForm(name=''){open(`<span class="tag">START WITH THE QUESTION</span><h2>What do you want to build?</h2><p>Describe the outcome and the thinking you need. This prototype saves requests on this device; it doesn’t send them to anyone.</p><form id="entry"><label for="title">Your project idea</label><input id="title" required maxlength="120" placeholder="I want to build…" value="${esc($('search').value)}"><label for="details">What are you trying to achieve?</label><textarea id="details" required maxlength="3000" placeholder="Who is it for? What have you tried? Where are you stuck?">${name?esc('Inspired by '+name+'’s example project. '):''}</textarea><label for="stage">Where are you now?</label><select id="stage"><option>Exploring an idea</option><option>Planning an approach</option><option>Building a first version</option><option>Improving something existing</option></select><button class="primary">Save project request</button></form>`);$('entry').onsubmit=e=>{e.preventDefault();const r={title:$('title').value.trim(),details:$('details').value.trim(),stage:$('stage').value};if(!r.title||!r.details)return;requests.unshift(r);if(save()){$('dialog').close();$('search').value='';setView('requests')}}}
function share(){open(`<span class="tag">THE REASONING IS THE STORY</span><h2>Share your thinking.</h2><p>Capture a case study draft on this device. Explain the decisions, not just the result.</p><form id="entry"><label for="title">Project title</label><input id="title" required maxlength="120"><label for="details">The problem, your approach, and the tradeoffs</label><textarea id="details" required maxlength="5000" placeholder="What did you choose, why, and what would you do differently?"></textarea><button class="primary">Save case study draft</button></form>${submissions.length?'<h3>Your saved drafts</h3>'+submissions.map(s=>`<details><summary>${esc(s.title)}</summary><p style="white-space:pre-wrap">${esc(s.details)}</p></details>`).join(''):''}`);$('entry').onsubmit=e=>{e.preventDefault();const s={title:$('title').value.trim(),details:$('details').value.trim()};if(!s.title||!s.details)return;submissions.unshift(s);if(save())open('<span class="tag">DRAFT SAVED ON THIS DEVICE</span><h2>Your thinking has a starting point.</h2><p>Open “Share your thinking” to read your saved draft. This draft has not been published.</p>')}}
function setView(v){view=v;filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='All'));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('search').value=b.dataset.query;setView('projects');$('sectionTitle').scrollIntoView({behavior:'smooth',block:'center'})});$('searchForm').onsubmit=e=>{e.preventDefault();render();$('sectionTitle').scrollIntoView({behavior:'smooth',block:'center'})};$('search').oninput=render;$('sort').onchange=render;$('grid').onclick=e=>{const p=e.target.closest('[data-project]'),n=e.target.closest('[data-person]');if(p)project(+p.dataset.project);if(n)person(+n.dataset.person)};$('request').onclick=()=>requestForm();$('share').onclick=share;document.querySelector('.close').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close()}};render();

// Hero question: type ~55ms/char, hold 3s, erase at 25ms; fade the matching illustration in as each new question begins.
const typed=$('rotatingProject'),heroArt=$('heroArt'),motion=window.matchMedia('(prefers-reduced-motion: reduce)');
projects.forEach(p=>{const i=new Image();i.src=`assets/${p.img}.png`});
let qi=0,timer;const wait=(ms)=>new Promise(r=>{timer=setTimeout(r,ms)});let run=0;
async function cycle(id){while(id===run){await wait(3000);if(id!==run)return;let t=projects[qi].headline;for(let n=t.length;n>=0&&id===run;n--){typed.textContent=t.slice(0,n);await wait(25)}qi=(qi+1)%projects.length;heroArt.classList.add('is-changing');await wait(200);heroArt.src=`assets/${projects[qi].img}.png`;heroArt.classList.remove('is-changing');t=projects[qi].headline;for(let n=1;n<=t.length&&id===run;n++){typed.textContent=t.slice(0,n);await wait(55)}}}
function restart(){clearTimeout(timer);run++;typed.textContent=projects[qi].headline;heroArt.src=`assets/${projects[qi].img}.png`;heroArt.classList.remove('is-changing');if(!motion.matches&&!document.hidden)cycle(run)}
document.addEventListener('visibilitychange',restart);motion.addEventListener('change',restart);restart();
